import Foundation
/// App UI language + string table. Every user-visible string should go through `L10n.t`.
enum AppUILanguage: String, CaseIterable, Identifiable {
    case system = "system"
    case en = "en"
    case ru = "ru"
    case es = "es"
    case de = "de"
    case fr = "fr"
    case pt = "pt"
    case zhHans = "zh-Hans"
    case ja = "ja"
    case ko = "ko"
    case it = "it"
    case tr = "tr"
    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .system: return L10n.t("appearance.system")
        case .en: return "English"
        case .ru: return "Русский"
        case .es: return "Español"
        case .de: return "Deutsch"
        case .fr: return "Français"
        case .pt: return "Português"
        case .zhHans: return "简体中文"
        case .ja: return "日本語"
        case .ko: return "한국어"
        case .it: return "Italiano"
        case .tr: return "Türkçe"
        }
    }
    var resolvedCode: String {
        if self != .system { return rawValue }
        let preferred = Locale.preferredLanguages.first ?? "en"
        let code = Locale(identifier: preferred).language.languageCode?.identifier ?? "en"
        switch code {
        case "ru": return "ru"
        case "es": return "es"
        case "de": return "de"
        case "fr": return "fr"
        case "pt": return "pt"
        case "zh": return "zh-Hans"
        case "ja": return "ja"
        case "ko": return "ko"
        case "it": return "it"
        case "tr": return "tr"
        default: return "en"
        }
    }
}

