    nonisolated(unsafe) static var code: String = "en"

    static func t(_ key: String) -> String {
        if let row = table[key] {
            return row[code] ?? row["en"] ?? key
        }
        return key
    }

    static func tf(_ key: String, _ args: CVarArg...) -> String {
        String(format: t(key), locale: Locale(identifier: code), arguments: args)
    }

